import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { type TokenName, tokens } from "../src/shared/config/tokens";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const outDir = join(root, "src", "styles", "generated");
const webFile = join(outDir, "tokens.css");

const header =
  "/* Generated by make tokens from src/shared/config/tokens.ts. Do not edit by hand. */\n";

const names = Object.keys(tokens) as TokenName[];
const block = (theme: "light" | "dark"): string =>
  names.map((n) => `  --${n}: ${tokens[n][theme]};`).join("\n");

const content = `${header}:root {\n${block("light")}\n}\n\n.dark {\n${block("dark")}\n}\n`;

const checkOnly = process.argv.includes("--check");
mkdirSync(outDir, { recursive: true });

let current: string | null = null;
try {
  current = readFileSync(webFile, "utf8");
} catch {
  current = null;
}
if (current !== content) {
  if (checkOnly) {
    console.error(`tokens: ${webFile} is stale; run make tokens`);
    process.exit(1);
  }
  writeFileSync(webFile, content);
  console.log(`tokens: wrote ${webFile}`);
} else if (checkOnly) {
  console.log("tokens: generated file is fresh");
}
